    #[test]
    fn context_rejects_invalid_parameters_with_specific_errors() {
        fn context_error(
            output_len: usize,
            salt_len: usize,
            t_cost: u32,
            m_cost: u32,
            parallelism: u32,
        ) -> Error {
            let mut output = vec![0u8; output_len];
            let salt = vec![0u8; salt_len];
            match Argon2Context::new(
                &mut output,
                b"password",
                &salt,
                None,
                None,
                t_cost,
                m_cost,
                parallelism,
            ) {
                Ok(_) => panic!("invalid Argon2 parameters should fail"),
                Err(error) => error,
            }
        }

        let cases = [
            (
                context_error(ARGON2_MIN_OUTLEN - 1, ARGON2_MIN_SALT_LENGTH, 1, 8, 1),
                crate::ErrorContext::Output,
            ),
            (
                context_error(ARGON2_MIN_OUTLEN, ARGON2_MIN_SALT_LENGTH - 1, 1, 8, 1),
                crate::ErrorContext::PasswordHashSalt,
            ),
            (
                context_error(ARGON2_MIN_OUTLEN, ARGON2_MIN_SALT_LENGTH, 1, 8, 0),
                crate::ErrorContext::Parallelism,
            ),
            (
                context_error(
                    ARGON2_MIN_OUTLEN,
                    ARGON2_MIN_SALT_LENGTH,
                    1,
                    ARGON2_MIN_MEMORY - 1,
                    1,
                ),
                crate::ErrorContext::MemoryCost,
            ),
            (
                context_error(ARGON2_MIN_OUTLEN, ARGON2_MIN_SALT_LENGTH, 1, 8, 2),
                crate::ErrorContext::MemoryCost,
            ),
            (
                context_error(ARGON2_MIN_OUTLEN, ARGON2_MIN_SALT_LENGTH, 0, 8, 1),
                crate::ErrorContext::TimeCost,
            ),
        ];

        for (error, expected_context) in cases {
            let context = match error {
                Error::InvalidLength { context, .. } | Error::InvalidValue { context, .. } => {
                    context
                }
                other => panic!("unexpected Argon2 error: {other:?}"),
            };
            assert_eq!(context, expected_context);
        }

        let salt = [0u8; ARGON2_MIN_SALT_LENGTH];
        for parallelism in [0, u32::MAX] {
            let mut output = [0u8; ARGON2_MIN_OUTLEN];
            assert!(
                argon2_hash(
                    1,
                    8,
                    parallelism,
                    b"password",
                    &salt,
                    None,
                    None,
                    &mut output,
                    Argon2Type::Argon2id,
                )
                .is_err()
            );
        }
    }

    /// Direct upper bounds are rejected before allocation or hashing. `t_cost`
    /// and `m_cost` are already `u32`; their representable maxima are valid,
    /// so only wider lengths and the 24-bit lane bound have a value above max.
    #[test]
    fn validator_rejects_representable_upper_bound_overflows() {
        if let Some(output_len) = ARGON2_MAX_OUTLEN.checked_add(1) {
            assert!(matches!(
                validate_argon2_pwhash_parameters(output_len, ARGON2_MIN_SALT_LENGTH, 1, 8, 1,),
                Err(Error::InvalidLength {
                    context: crate::ErrorContext::Output,
                    ..
                })
            ));
        }
        if let Some(salt_len) = ARGON2_MAX_SALT_LENGTH.checked_add(1) {
            assert!(matches!(
                validate_argon2_pwhash_parameters(ARGON2_MIN_OUTLEN, salt_len, 1, 8, 1,),
                Err(Error::InvalidLength {
                    context: crate::ErrorContext::PasswordHashSalt,
                    ..
                })
            ));
        }
        assert!(matches!(
            validate_argon2_pwhash_parameters(
                ARGON2_MIN_OUTLEN,
                ARGON2_MIN_SALT_LENGTH,
                1,
                8 * (ARGON2_MAX_LANES + 1),
                ARGON2_MAX_LANES + 1,
            ),
            Err(Error::InvalidValue {
                context: crate::ErrorContext::Parallelism,
                ..
            })
        ));
        // `ARGON2_MAX_MEMORY` is `u32::MAX` on 64-bit targets, so an
        // over-maximum value only exists on 32-bit ones.
        if let Some(m_cost) = ARGON2_MAX_MEMORY.checked_add(1) {
            assert!(matches!(
                validate_argon2_pwhash_parameters(
                    ARGON2_MIN_OUTLEN,
                    ARGON2_MIN_SALT_LENGTH,
                    1,
                    m_cost,
                    1,
                ),
                Err(Error::InvalidValue {
                    context: crate::ErrorContext::MemoryCost,
                    ..
                })
            ));
        }
    }

